namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Location { get; set; } = "";
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = "";
    public int InstructorId { get; set; }
    public string InstructorName { get; set; } = "";
    public bool IsFeatured { get; set; }
    public int MaxEnrollment { get; set; }
    public int CurrentEnrollment { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }

    [StringLength(500)]
    public string? Notes { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Pure and applied mathematics, statistics, and data analysis." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Literature, writing, rhetoric, and language studies." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and their impact on the modern world." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Ada Lovelace", Title = "Professor of Computer Science", Bio = "Specializes in algorithms and programming language theory. Published over 40 peer-reviewed papers on computational complexity.", Email = "alovelace@university.edu" },
            new() { Id = 2, Name = "Dr. Alan Turing", Title = "Associate Professor of Computer Science", Bio = "Expert in artificial intelligence and machine learning. Leads the university's AI research lab.", Email = "aturing@university.edu" },
            new() { Id = 3, Name = "Dr. Emmy Noether", Title = "Professor of Mathematics", Bio = "Renowned for contributions to abstract algebra and theoretical physics. Recipient of the Distinguished Teaching Award.", Email = "enoether@university.edu" },
            new() { Id = 4, Name = "Dr. Richard Feynman", Title = "Professor of Physics", Bio = "Known for engaging lectures and contributions to quantum electrodynamics. Author of several popular science books.", Email = "rfeynman@university.edu" },
            new() { Id = 5, Name = "Dr. Maya Angelou", Title = "Professor of English", Bio = "Award-winning author and poet. Focuses on creative writing and American literature.", Email = "mangelou@university.edu" },
            new() { Id = 6, Name = "Dr. Howard Zinn", Title = "Associate Professor of History", Bio = "Specializes in American social movements and labor history. Author of multiple historical analyses.", Email = "hzinn@university.edu" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "An introductory course covering fundamental programming concepts, data types, control structures, and basic algorithms. Students will learn to write programs in Python and develop computational thinking skills.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, DepartmentName = "Computer Science", InstructorId = 1, InstructorName = "Dr. Ada Lovelace", IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures and Algorithms", Description = "In-depth study of data structures including trees, graphs, hash tables, and heaps. Covers algorithm design techniques such as divide-and-conquer, dynamic programming, and greedy algorithms. Prerequisites: CS 101, MATH 201.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Location = "Science Hall 305", DepartmentId = 1, DepartmentName = "Computer Science", InstructorId = 1, InstructorName = "Dr. Ada Lovelace", IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 3, Code = "CS 420", Title = "Artificial Intelligence", Description = "Explores the principles and techniques of artificial intelligence including search, knowledge representation, machine learning, and neural networks. Includes hands-on projects building intelligent agents.", Credits = 3, Schedule = "Mon/Wed 2:00–3:30 PM", Location = "Tech Center 110", DepartmentId = 1, DepartmentName = "Computer Science", InstructorId = 2, InstructorName = "Dr. Alan Turing", IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 44 },
            new() { Id = 4, Code = "MATH 101", Title = "Calculus I", Description = "Introduction to differential calculus covering limits, continuity, derivatives, and applications. Emphasis on problem-solving and mathematical reasoning.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 101", DepartmentId = 2, DepartmentName = "Mathematics", InstructorId = 3, InstructorName = "Dr. Emmy Noether", IsFeatured = true, MaxEnrollment = 150, CurrentEnrollment = 130 },
            new() { Id = 5, Code = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, and eigenvalues. Applications to computer graphics, data science, and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00–10:30 AM", Location = "Math Building 203", DepartmentId = 2, DepartmentName = "Mathematics", InstructorId = 3, InstructorName = "Dr. Emmy Noether", IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 62 },
            new() { Id = 6, Code = "MATH 350", Title = "Probability and Statistics", Description = "Introduction to probability theory, random variables, distributions, estimation, and hypothesis testing. Practical applications using R and real-world datasets.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Math Building 105", DepartmentId = 2, DepartmentName = "Mathematics", InstructorId = 3, InstructorName = "Dr. Emmy Noether", IsFeatured = false, MaxEnrollment = 90, CurrentEnrollment = 71 },
            new() { Id = 7, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Covers Newton's laws, conservation of energy and momentum, rotational motion, and oscillations. Includes weekly lab sessions.", Credits = 4, Schedule = "Tue/Thu 1:00–2:30 PM", Location = "Physics Lab 100", DepartmentId = 3, DepartmentName = "Physics", InstructorId = 4, InstructorName = "Dr. Richard Feynman", IsFeatured = true, MaxEnrollment = 100, CurrentEnrollment = 88 },
            new() { Id = 8, Code = "PHYS 301", Title = "Quantum Mechanics", Description = "Introduction to quantum mechanics: wave-particle duality, Schrödinger equation, quantum states, and measurement. Prerequisites: PHYS 101, MATH 201.", Credits = 3, Schedule = "Mon/Wed 10:00–11:30 AM", Location = "Physics Lab 210", DepartmentId = 3, DepartmentName = "Physics", InstructorId = 4, InstructorName = "Dr. Richard Feynman", IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 35 },
            new() { Id = 9, Code = "ENG 101", Title = "English Composition", Description = "Develops college-level writing skills through essays, research papers, and peer review. Focuses on argumentation, critical analysis, and effective communication.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Humanities Hall 302", DepartmentId = 4, DepartmentName = "English", InstructorId = 5, InstructorName = "Dr. Maya Angelou", IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 28 },
            new() { Id = 10, Code = "ENG 250", Title = "Creative Writing", Description = "Workshop-based course exploring fiction, poetry, and creative nonfiction. Students develop their voice through writing exercises, peer workshops, and revision.", Credits = 3, Schedule = "Tue/Thu 3:00–4:30 PM", Location = "Humanities Hall 105", DepartmentId = 4, DepartmentName = "English", InstructorId = 5, InstructorName = "Dr. Maya Angelou", IsFeatured = true, MaxEnrollment = 20, CurrentEnrollment = 19 },
            new() { Id = 11, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, cultures, and events from antiquity through the late medieval period. Examines social, political, and economic developments across continents.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:30 PM", Location = "Liberal Arts 200", DepartmentId = 5, DepartmentName = "History", InstructorId = 6, InstructorName = "Dr. Howard Zinn", IsFeatured = false, MaxEnrollment = 100, CurrentEnrollment = 76 },
            new() { Id = 12, Code = "HIST 320", Title = "Modern American History", Description = "In-depth study of American history from the Reconstruction era to the present. Covers industrialization, civil rights movements, foreign policy, and cultural transformations.", Credits = 3, Schedule = "Mon/Wed 3:00–4:30 PM", Location = "Liberal Arts 310", DepartmentId = 5, DepartmentName = "History", InstructorId = 6, InstructorName = "Dr. Howard Zinn", IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 42 },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId, int? minCredits, int? maxCredits)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (minCredits.HasValue)
            query = query.Where(c => c.Credits >= minCredits.Value);

        if (maxCredits.HasValue)
            query = query.Where(c => c.Credits <= maxCredits.Value);

        return query.ToList();
    }
}

