arguments.file_text:
@page "/courses"
@rendermode InteractiveServer
@inject CourseCatalog.Services.CatalogService Catalog

<PageTitle>Course Catalog – Browse Courses</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<div class="card mb-4 shadow-sm">
    <div class="card-body">
        <div class="row g-3">
            <div class="col-md-4">
                <label for="search" class="form-label">Search</label>
                <input id="search" type="text" class="form-control" placeholder="Search by title, code, or instructor…"
                       @bind="searchTerm" @bind:event="oninput" />
            </div>
            <div class="col-md-3">
                <label for="department" class="form-label">Department</label>
                <select id="department" class="form-select" @bind="selectedDepartmentId">
                    <option value="0">All Departments</option>
                    @foreach (var dept in departments)
                    {
                        <option value="@dept.Id">@dept.Name</option>
                    }
                </select>
            </div>
            <div class="col-md-2">
                <label for="minCredits" class="form-label">Min Credits</label>
                <select id="minCredits" class="form-select" @bind="minCredits">
                    <option value="">Any</option>
                    <option value="3">3</option>
                    <option value="4">4</option>
                </select>
            </div>
            <div class="col-md-2">
                <label for="maxCredits" class="form-label">Max Credits</label>
                <select id="maxCredits" class="form-select" @bind="maxCredits">
                    <option value="">Any</option>
                    <option value="3">3</option>
                    <option value="4">4</option>
                </select>
            </div>
            <div class="col-md-1 d-flex align-items-end">
                <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear</button>
            </div>
        </div>
    </div>
</div>

<p class="text-muted mb-3">Showing @filteredCourses.Count course(s)</p>

<div class="table-responsive">
    <table class="table table-hover align-middle">
        <thead class="table-light">
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Instructor</th>
                <th>Schedule</th>
                <th>Availability</th>
                <th></th>
